SELECT '#ju_user cols'; SELECT TABLE_NAME,ORDINAL_POSITION,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,COLUMN_COMMENT FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('ju_user','ju_user_detail','ju_auth','ju_auth_detail') ORDER BY 1,2;
SELECT '#keys'; SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('ju_user','ju_user_detail','ju_auth') GROUP BY 1,2,3;
SELECT '#fks'; SELECT TABLE_NAME,CONSTRAINT_NAME,COLUMN_NAME,REFERENCED_TABLE_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('ju_user','ju_user_detail') AND REFERENCED_TABLE_NAME IS NOT NULL;
SELECT '#users'; SELECT u.USER_ID,u.LOGIN_ID,LEFT(u.USER_PW_HASH,4) hash_prefix,LENGTH(u.USER_PW_HASH) hash_len,u.AUTH_ID,u.USE_YN,d.USER_NM,d.PW_CHANGE_DT,d.LOGIN_FAIL_CNT FROM ju_user u LEFT JOIN ju_user_detail d ON d.USER_ID=u.USER_ID;
SELECT '#auth'; SELECT a.AUTH_ID,a.AUTH_TYPE,a.USE_YN,LENGTH(a.AUTH_ATTR) attr_len,LEFT(a.AUTH_ATTR,30) attr_head FROM ju_auth a ORDER BY 1;
SELECT '#auth type codes'; SELECT COM_CD,COM_VAL FROM ju_com_code WHERE GRP_CD=(SELECT GRP_CD FROM ju_com_code WHERE COM_CD='AUTH0001' LIMIT 1) ORDER BY 1;
SELECT '#tables'; SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND (TABLE_NAME LIKE 'ju_user%' OR TABLE_NAME LIKE 'ju_client%' OR TABLE_NAME LIKE '%login%' OR TABLE_NAME LIKE '%hist%') ORDER BY 1;
